-- ===========================================================================
-- HAND-WRITTEN — everything below this line is reviewed by a human, not
-- generated.
--
-- NOTE ON CREATOR FOREIGN KEYS: `family` and `child` carry `created_by_user_id`
-- as NOT NULL REFERENCES app_user, generated above. There is no anonymous or
-- system path that registers a family — it is entered by a signed-in member of
-- staff, and the row names them. `registration_draft` carries the same key for
-- a different reason: it is half of what makes a draft usable only by the
-- person who created it.
--
-- NOTE ON `registration_draft.session_id`: mandatory, and deliberately carrying
-- NO foreign key, exactly as `audit_log.session_id` does. A session row must
-- stay purgeable, and a draft outliving its session by a few minutes is
-- harmless — the draft is refused on resolution because the session no longer
-- matches, not because the reference broke.
-- ===========================================================================

-- --- fa_normalize: the one search normaliser -------------------------------
--
-- Every `search_*` column is this function applied to the column beside it,
-- and a CHECK asserts so. It is used identically on the stored value and on an
-- incoming query, which is what makes search unable to disagree with storage.
--
-- THIS DOES NOT CONTRADICT the Milestone 2 decision against yeh/kaf folding.
-- That rule governs STORED VALUES AND UNIQUENESS: "اتاق ۱" stays exactly as
-- typed and two spellings stay two rows. Here the stored name is untouched and
-- the folding lives only in a derived key. Both rules say the same thing —
-- never rewrite what a user typed.
--
-- Written with Unicode escapes rather than literal characters so the mapping is
-- reviewable left-to-right and cannot be mangled by an editor that reorders
-- bidirectional text.
--
--   MAPPED (11):  064A ي, 0649 ى, 0626 ئ  -> 06CC ی      Arabic yeh forms
--                 0643 ك                  -> 06A9 ک      Arabic kaf
--                 0623 أ, 0625 إ, 0622 آ, 0671 ٱ -> 0627 ا   hamza/madda alefs
--                 0629 ة, 06C0 ۀ          -> 0647 ه      teh marbuta, heh+hamza
--                 0624 ؤ                  -> 0648 و      waw with hamza
--   MAPPED (20):  06F0-06F9, 0660-0669    -> 0-9         Persian, Arabic-Indic
--   DELETED (15): 200C ZWNJ, 200D ZWJ, 0640 tatweel,
--                 064B-0655 harakat, 0670 superscript alef
--
-- `translate` removes any character in `from` that has no counterpart in `to`,
-- which is what makes one call do both jobs.
CREATE OR REPLACE FUNCTION "fa_normalize"(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
    SELECT btrim(regexp_replace(
        lower(translate(
            value,
            U&'\064A\0649\0626\0643\0623\0625\0622\0671\0629\06C0\0624'
                || U&'\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9'
                || U&'\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669'
                || U&'\200C\200D\0640\064B\064C\064D\064E\064F\0650\0651\0652\0653\0654\0655\0670',
            U&'\06CC\06CC\06CC\06A9\0627\0627\0627\0627\0647\0647\0648'
                || '0123456789'
                || '0123456789'
        )),
        '\s+', ' ', 'g'));
$fn$;

-- --- search_like_escape: wildcards are data, not syntax ---------------------
--
-- `fa_normalize` deliberately leaves `%`, `_` and `\` alone — they are
-- characters somebody typed. A prefix search built without this would turn a
-- query of `%` into "match every family in the clinic", which is both a wrong
-- answer and an accidental bulk disclosure.
--
-- Backslash is replaced FIRST, so the escape character is itself escaped and
-- cannot be used to neutralise the two replacements that follow. Every prefix
-- and substring predicate is written
-- `col LIKE search_like_escape(fa_normalize($1)) || '%' ESCAPE '\'`.
--
-- WATCH THE ESCAPE CLAUSE IN TYPESCRIPT. Inside a template literal that must be
-- written `ESCAPE '\\'`: `\'` is an escaped quote in JavaScript, so the obvious
-- spelling reaches PostgreSQL as `ESCAPE ''` — an empty escape character, which
-- turns escaping off entirely. The mistake hides itself, because a query of `%`
-- then becomes a search for a name beginning with a literal backslash and still
-- returns nothing; what breaks is finding the family whose name genuinely
-- contains a `%`. An integration test pins both halves.
--
-- NAMED `search_like_escape` RATHER THAN `like_escape`, deliberately.
-- PostgreSQL already ships `pg_catalog.like_escape(text, text)` and
-- `like_escape(bytea, bytea)`. A one-argument `public.like_escape` resolves
-- correctly by arity, but it leaves three functions of that name in the
-- catalogue: a by-name existence test would pass even if ours were dropped, and
-- a future caller writing the two-argument form would silently get the built-in
-- while believing they had this. The prefix costs one word and removes both.
CREATE OR REPLACE FUNCTION "search_like_escape"(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
    SELECT replace(replace(replace(value, '\', '\\'), '%', '\%'), '_', '\_');
$fn$;

-- --- clinic_date: the clinic's own calendar day -----------------------------
--
-- The clinic is in Iran, so "today" means today in Tehran — not in UTC, not in
-- whatever timezone the Node process runs under, and not in whatever the
-- session `TimeZone` happens to be set to. Those answers differ for three and a
-- half hours of every day, which is long enough for a birth date entered in the
-- evening to be wrongly refused as being in the future.
--
-- `AT TIME ZONE` with a literal zone name is explicit, so the result does not
-- depend on any session setting. That is also why this is the authority rather
-- than a Node helper: there is only one clock, and it is the database's.
--
-- STABLE, not IMMUTABLE — timezone definitions can change — which is precisely
-- why the future-birth-date rule is a statement-level check in the service and
-- not a CHECK constraint. PostgreSQL will not accept a non-immutable function
-- in a CHECK, and pretending otherwise would be the wrong way to win.
--
-- The parameter exists so tests can pass an exact instant; production calls it
-- with no argument and gets the transaction clock.
--
-- WHAT THIS IS NOT FOR: resolving a tariff. That uses the service date the
-- caller supplies, because the price of a session is decided by the day the
-- session happened.
CREATE OR REPLACE FUNCTION "clinic_date"(moment timestamptz DEFAULT transaction_timestamp())
    RETURNS date LANGUAGE sql STABLE PARALLEL SAFE AS $fn$
    SELECT (moment AT TIME ZONE 'Asia/Tehran')::date;
$fn$;

-- --- audit_identifiers_masked: the database half of the masking rule --------
--
-- `audit_log` is append-only and permanent, so a national identifier or a phone
-- number copied into it becomes a second, undeletable store of that identifier,
-- kept to answer a question that never needed the value. The application masks
-- to the last four digits in one mapper and refuses anything else in
-- `assertAuditPayloadSafe`; this makes PostgreSQL refuse it too, so a future
-- call site, a data-fix script or a psql session cannot write one.
--
-- Recursive PL/pgSQL rather than a `jsonb_path_exists` expression, deliberately.
-- JSON path can address a key BY NAME but cannot match a key PATTERN, and the
-- rule has to catch `primaryMobile` and `guardian_mobile` as well as `mobile`.
-- Keys are normalised the same way the TypeScript guard normalises them —
-- lower-cased with separators stripped — and matched as substrings.
--
-- The shapes are EXACT, not "begins with an asterisk". Six asterisks and four
-- digits cannot be produced by a ten-digit identifier, so a full value is
-- structurally incapable of passing; a prefix rule would have accepted
-- `*1234567890`. A non-string value is refused along with everything else: a
-- number under one of these keys is an identifier that has already lost its
-- leading zero.
--
-- Unrelated numeric facts are untouched. `priceToman` reaches ten digits under
-- the Milestone 2 tariff ceiling and is none of this function's business — the
-- rule is keyed on the field name, never on the shape of an arbitrary value.
CREATE OR REPLACE FUNCTION "audit_identifiers_masked"(payload jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $fn$
DECLARE
    item       jsonb;
    entry      record;
    normalized text;
    expected   text;
BEGIN
    IF payload IS NULL THEN
        RETURN true;
    END IF;

    IF jsonb_typeof(payload) = 'array' THEN
        FOR item IN SELECT value FROM jsonb_array_elements(payload) LOOP
            IF NOT "audit_identifiers_masked"(item) THEN
                RETURN false;
            END IF;
        END LOOP;
        RETURN true;
    END IF;

    IF jsonb_typeof(payload) <> 'object' THEN
        RETURN true;
    END IF;

    FOR entry IN SELECT key, value FROM jsonb_each(payload) LOOP
        normalized := regexp_replace(lower(entry.key), '[^a-z0-9]', '', 'g');

        expected := CASE
            WHEN normalized LIKE '%nationalid%' THEN '^[*]{6}[0-9]{4}$'
            WHEN normalized LIKE '%mobile%'     THEN '^[*]{7}[0-9]{4}$'
            WHEN normalized LIKE '%landline%'   THEN '^[*]{6,7}[0-9]{4}$'
            WHEN normalized LIKE '%phone%'      THEN '^[*]{6,7}[0-9]{4}$'
            ELSE NULL
        END;

        -- A JSON null is permitted, so "a number was added" and "a number was
        -- changed" stay different facts in the trail.
        IF expected IS NOT NULL AND jsonb_typeof(entry.value) <> 'null' THEN
            IF jsonb_typeof(entry.value) <> 'string'
                OR (entry.value #>> '{}') !~ expected
            THEN
                RETURN false;
            END IF;
        END IF;

        IF NOT "audit_identifiers_masked"(entry.value) THEN
            RETURN false;
        END IF;
    END LOOP;

    RETURN true;
END;
$fn$;

ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_masked_identifiers_chk"
    CHECK (
        "audit_identifiers_masked"("before")
        AND "audit_identifiers_masked"("after")
        AND "audit_identifiers_masked"("metadata")
    );

-- --- child file numbers ------------------------------------------------------
--
-- Staff never type or choose a file number: a typed identifier on the busiest
-- form in the clinic is a duplicate-key error waiting to happen, and two people
-- registering at once would eventually pick the same one.
--
-- Gaps are expected and are not a defect. A rolled-back transaction burns a
-- number, which is the correct trade for never issuing one twice. Nothing
-- anywhere asserts the sequence is gap-free.
--
-- Starting at 10001 so every file number has the same width for a long time,
-- which matters when somebody reads one aloud over the phone.
CREATE SEQUENCE "child_file_number_seq" START WITH 10001 INCREMENT BY 1 NO CYCLE;

-- --- family CHECK constraints -----------------------------------------------

ALTER TABLE "family" ADD CONSTRAINT "family_name_chk"
    CHECK (
        "family_name" = btrim("family_name")
        AND btrim("family_name") <> ''
        AND length("family_name") <= 120
    );

-- The derived key is the function's output or the row does not exist. Without
-- this, a future INSERT that forgot to normalise would produce a family that is
-- unfindable by the search that was built to find it.
ALTER TABLE "family" ADD CONSTRAINT "family_search_name_chk"
    CHECK ("search_family_name" = "fa_normalize"("family_name"));

ALTER TABLE "family" ADD CONSTRAINT "family_address_chk"
    CHECK (
        "address" IS NULL
        OR (
            "address" = btrim("address")
            AND btrim("address") <> ''
            AND length("address") <= 500
        )
    );

ALTER TABLE "family" ADD CONSTRAINT "family_note_chk"
    CHECK (
        "note" IS NULL
        OR (
            "note" = btrim("note")
            AND btrim("note") <> ''
            AND length("note") <= 2000
        )
    );

ALTER TABLE "family" ADD CONSTRAINT "family_deactivated_consistency_chk"
    CHECK (("status" = 'INACTIVE') = ("deactivated_at" IS NOT NULL));

-- --- guardian CHECK constraints ----------------------------------------------

ALTER TABLE "guardian" ADD CONSTRAINT "guardian_full_name_chk"
    CHECK (
        "full_name" = btrim("full_name")
        AND btrim("full_name") <> ''
        AND length("full_name") <= 120
    );

ALTER TABLE "guardian" ADD CONSTRAINT "guardian_search_name_chk"
    CHECK ("search_full_name" = "fa_normalize"("full_name"));

-- `OTHER` carries a note and nothing else does, so the value cannot become a
-- black hole and a named relationship cannot carry contradictory free text.
ALTER TABLE "guardian" ADD CONSTRAINT "guardian_relationship_note_chk"
    CHECK (
        (("relationship" = 'OTHER') = ("relationship_note" IS NOT NULL))
        AND (
            "relationship_note" IS NULL
            OR (
                "relationship_note" = btrim("relationship_note")
                AND btrim("relationship_note") <> ''
                AND length("relationship_note") <= 120
            )
        )
    );

-- Canonical national form, digits only. The web tier folds Persian digits,
-- `+98`, spaces and hyphens before anything reaches here, so a non-canonical
-- value means something bypassed that edge.
ALTER TABLE "guardian" ADD CONSTRAINT "guardian_mobile_chk"
    CHECK ("mobile" IS NULL OR "mobile" ~ '^09[0-9]{9}$');

ALTER TABLE "guardian" ADD CONSTRAINT "guardian_landline_chk"
    CHECK ("landline" IS NULL OR "landline" ~ '^0[1-9][0-9]{8,9}$');

-- The primary contact is reachable, by mobile OR landline. A mobile is
-- preferred and is not required: a family reachable only on a landline is a
-- real family, and refusing it would refuse a patient.
ALTER TABLE "guardian" ADD CONSTRAINT "guardian_primary_needs_contact_chk"
    CHECK (
        "is_primary_contact" = false
        OR "mobile" IS NOT NULL
        OR "landline" IS NOT NULL
    );

-- --- child CHECK constraints -------------------------------------------------

ALTER TABLE "child" ADD CONSTRAINT "child_first_name_chk"
    CHECK (
        "first_name" = btrim("first_name")
        AND btrim("first_name") <> ''
        AND length("first_name") <= 120
    );

ALTER TABLE "child" ADD CONSTRAINT "child_last_name_chk"
    CHECK (
        "last_name" = btrim("last_name")
        AND btrim("last_name") <> ''
        AND length("last_name") <= 120
    );

ALTER TABLE "child" ADD CONSTRAINT "child_search_first_name_chk"
    CHECK ("search_first_name" = "fa_normalize"("first_name"));

ALTER TABLE "child" ADD CONSTRAINT "child_search_last_name_chk"
    CHECK ("search_last_name" = "fa_normalize"("last_name"));

-- A loose lower bound only. The upper bound is "not after today in Tehran",
-- which `clinic_date()` answers and which is STABLE, so it cannot live here;
-- the service enforces it and raises CHILD_BIRTH_DATE_IN_FUTURE.
ALTER TABLE "child" ADD CONSTRAINT "child_birth_date_chk"
    CHECK ("birth_date" >= DATE '1900-01-01');

ALTER TABLE "child" ADD CONSTRAINT "child_file_number_chk"
    CHECK ("file_number" ~ '^[0-9]{5,10}$');

-- Shape only. The check digit is verified in the shared contract, because a
-- transposed digit is an ordinary typing mistake and deserves an ordinary
-- validation message rather than a constraint failure.
ALTER TABLE "child" ADD CONSTRAINT "child_national_id_chk"
    CHECK ("national_id" IS NULL OR "national_id" ~ '^[0-9]{10}$');

ALTER TABLE "child" ADD CONSTRAINT "child_legacy_file_number_chk"
    CHECK (
        "legacy_paper_file_number" IS NULL
        OR (
            "legacy_paper_file_number" = btrim("legacy_paper_file_number")
            AND btrim("legacy_paper_file_number") <> ''
            AND length("legacy_paper_file_number") <= 40
        )
    );

ALTER TABLE "child" ADD CONSTRAINT "child_referral_source_chk"
    CHECK (
        "referral_source" IS NULL
        OR (
            "referral_source" = btrim("referral_source")
            AND btrim("referral_source") <> ''
            AND length("referral_source") <= 200
        )
    );

ALTER TABLE "child" ADD CONSTRAINT "child_note_chk"
    CHECK (
        "note" IS NULL
        OR (
            "note" = btrim("note")
            AND btrim("note") <> ''
            AND length("note") <= 2000
        )
    );

ALTER TABLE "child" ADD CONSTRAINT "child_deactivated_consistency_chk"
    CHECK (("status" = 'INACTIVE') = ("deactivated_at" IS NOT NULL));

-- --- registration_draft CHECK constraints ------------------------------------

-- SHA-256 output is exactly 32 bytes, as on `user_session`. A shorter value
-- would mean something other than a hash reached this column.
ALTER TABLE "registration_draft" ADD CONSTRAINT "registration_draft_token_hash_length_chk"
    CHECK (octet_length("token_hash") = 32);

-- Both timestamps come from the same PostgreSQL transaction clock, so a draft
-- that expires before it was created is not a clock-skew symptom; it is a bug.
ALTER TABLE "registration_draft" ADD CONSTRAINT "registration_draft_expiry_chk"
    CHECK ("expires_at" > "created_at");

-- A draft names exactly what its purpose requires and nothing more. A
-- FAMILY_CREATE draft that somehow carried a target family would be describing
-- an update, and the confirmation would perform the wrong write.
ALTER TABLE "registration_draft" ADD CONSTRAINT "registration_draft_target_chk"
    CHECK (
        ("purpose" = 'FAMILY_CREATE' AND "target_family_id" IS NULL     AND "target_child_id" IS NULL)
        OR ("purpose" = 'FAMILY_UPDATE' AND "target_family_id" IS NOT NULL AND "target_child_id" IS NULL)
        OR ("purpose" = 'CHILD_CREATE'  AND "target_family_id" IS NOT NULL AND "target_child_id" IS NULL)
        OR ("purpose" = 'CHILD_UPDATE'  AND "target_family_id" IS NOT NULL AND "target_child_id" IS NOT NULL)
    );

-- --- partial unique indexes --------------------------------------------------
--
-- Three rules Prisma cannot express, because each is conditional.

-- At most one primary contact per family. "At least one guardian" is a service
-- invariant, not a database one, and the schema comment says so rather than
-- implying a guarantee the database does not make.
CREATE UNIQUE INDEX "guardian_one_primary_per_family_uq"
    ON "guardian" ("family_id")
    WHERE "is_primary_contact";

-- A national identifier names exactly one person, so two children carrying the
-- same one is a data error rather than a coincidence — the one duplicate rule
-- with no override. Partial, because absence is the common case and NULLs must
-- not collide.
CREATE UNIQUE INDEX "child_national_id_uq"
    ON "child" ("national_id")
    WHERE "national_id" IS NOT NULL;

-- One paper file, one child. Independent of `file_number`, so the clinic's
-- existing numbering and the generated one coexist.
CREATE UNIQUE INDEX "child_legacy_paper_file_number_uq"
    ON "child" ("legacy_paper_file_number")
    WHERE "legacy_paper_file_number" IS NOT NULL;

-- --- no-delete enforcement (reuses the Milestone 1 shared function) ----------
--
-- A family and a child are permanent historical records: a child will be named
-- by a session charge and a family holds the balance. Deactivation is
-- `status = INACTIVE`. The TRUNCATE triggers are not optional — TRUNCATE
-- bypasses row-level triggers entirely.

CREATE TRIGGER "family_no_delete"
    BEFORE DELETE ON "family"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "family_no_truncate"
    BEFORE TRUNCATE ON "family"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "child_no_delete"
    BEFORE DELETE ON "child"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "child_no_truncate"
    BEFORE TRUNCATE ON "child"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

-- `guardian` deliberately carries no delete trigger: guardians are current
-- configuration, replaced wholesale with their family and recorded in
-- `audit_log` as values, exactly like `therapist_service` and `room_service`.
--
-- `registration_draft` deliberately carries no delete or truncate trigger
-- either, for a different reason: a draft is transient workflow state that is
-- meant to be consumed and physically removed. Deletion is how it ends.

-- --- child identity immutability ---------------------------------------------
--
-- What a child *is* does not change. Above all, `family_id` does not change:
-- moving a child between families rewrites who owes for every session that
-- child has ever had, and a future edit endpoint, a data-fix script or a
-- debugging session at a psql prompt must not be able to do it by accident. A
-- genuine reassignment is a designed, audited repair operation belonging to the
-- milestone that owns financial history.
--
-- `file_number` is here because it is quoted aloud, printed and written on a
-- paper file; a number that can change is not an identifier. `created_at` and
-- `created_by_user_id` are here because they are the record's provenance.
--
-- Raises restrict_violation (SQLSTATE 23001), the same stable code
-- `raise_append_only_violation` uses, so every "the database refuses to rewrite
-- this" failure asserts on one code.
CREATE OR REPLACE FUNCTION "enforce_child_identity_immutability"() RETURNS trigger
    LANGUAGE plpgsql AS $fn$
BEGIN
    IF NEW."id"                 IS DISTINCT FROM OLD."id"
        OR NEW."family_id"          IS DISTINCT FROM OLD."family_id"
        OR NEW."file_number"        IS DISTINCT FROM OLD."file_number"
        OR NEW."created_at"         IS DISTINCT FROM OLD."created_at"
        OR NEW."created_by_user_id" IS DISTINCT FROM OLD."created_by_user_id"
    THEN
        RAISE EXCEPTION
            'child % identity is immutable; family_id, file_number, created_at, created_by_user_id and id cannot change',
            OLD."id"
            USING ERRCODE = 'restrict_violation';
    END IF;

    RETURN NEW;
END;
$fn$;

CREATE TRIGGER "child_enforce_identity_immutability"
    BEFORE UPDATE ON "child"
    FOR EACH ROW EXECUTE FUNCTION "enforce_child_identity_immutability"();

-- NOTE ON COMPLETENESS: as in both earlier migrations, a table owner can still
-- run `ALTER TABLE ... DISABLE TRIGGER`. Closing that gap needs a runtime
-- database role that does not own these tables. That remains a production
-- hardening item, unchanged by this milestone.
